"""Extract every panel attempt's final reply from the recorded traces of a run."""
import json, glob, os, sys

RUNS = {
    'panel': '/workspace/runs/fb204702a72dc3e2168539118386bdb4a460371c',
    'abbrev': '/workspace/runs/13b8664bc78f4264c10a36e67028dfdb45cecde2',
    'affix': '/workspace/runs/0d30915e47bd94e37ce6b62f68b611bff0458b14',
    'snap': '/workspace/runs/53597ebc133c7eb0dff1937725f3b72f1c09b4b5',
    'baseline': '/workspace/runs/9f49dd7221d29df0c6f8b80f8f04a8b2b2b607f7',
}
TASKS = ['USPTO', 'Symptom2Disease', 'LawBench']


def replies_of(trace):
    """Every final reply the sample's trace records, in call order."""
    lines = []
    main = trace['messages']
    if main:
        lines.append(main)
    lines.extend(trace['side_calls'])
    out = []
    for line in lines:
        if not line:
            continue
        last = line[-1]
        if last.get('role') != 'assistant' or last.get('tool_calls'):
            continue
        content = last.get('content')
        if isinstance(content, list):
            content = "".join(b if isinstance(b, str) else b.get('text', '') for b in content)
        if isinstance(content, str) and content.strip():
            out.append(content)
    return out


def load(run_key, tasks=TASKS):
    root = RUNS[run_key]
    rows = {}
    for task in tasks:
        for path in sorted(glob.glob(f'{root}/{task}/conversations/*/sample-*.json')):
            trace = json.load(open(path))
            key = (task, trace['example_index'], trace['sample_index'])
            rows[key] = {
                'prediction': trace['prediction'], 'target': trace['target'],
                'was_correct': trace['was_correct'], 'status': trace['status'],
                'replies': replies_of(trace), 'path': path,
                'elapsed': trace['elapsed_seconds'], 'calls': trace['usage']['model_calls'],
            }
    return rows


if __name__ == '__main__':
    for key in RUNS:
        rows = load(key)
        for task in TASKS:
            sub = [r for k, r in rows.items() if k[0] == task]
            reps = [len(r['replies']) for r in sub]
            ok = sum(r['was_correct'] for r in sub)
            print(f'{key:9s} {task:16s} n={len(sub):3d} correct={ok:3d} '
                  f'replies/sample min={min(reps) if reps else 0} max={max(reps) if reps else 0} '
                  f'mean={sum(reps)/len(reps):.2f} '
                  f'dup_pred={sum(r["prediction"] in r["replies"] for r in sub)}')

