"""Score many candidate selection rules over the recorded panel replies."""
import json, sys, collections
sys.path.insert(0, '/tmp/analysis')
from rules import A, scored_rows, spaces, correct, TASKS


def comps(answer, sep):
    text = (answer or '').strip().lower()
    text = ' '.join(text.split())
    if sep and sep in text:
        return [p.strip() for p in text.split(sep) if p.strip()]
    return [text] if text else []


def rule_current(answers, sep):
    counts = collections.OrderedDict()
    for a in answers:
        counts.setdefault(a, []).append(a)
    best = max(counts, key=lambda k: len(counts[k]))
    return best


def rule_longest(answers, sep):
    return max(answers, key=len)


def rule_shortest(answers, sep):
    return min(answers, key=len)


def rule_component_majority(answers, sep, threshold=0.5):
    """The reply whose component set is closest to the panel's component majority."""
    sets = [set(comps(a, sep)) for a in answers]
    all_c = set().union(*sets) if sets else set()
    support = {c: sum(1 for s in sets if c in s) / len(sets) for c in all_c}
    target = {c for c, v in support.items() if v > threshold}
    def score(a):
        s = set(comps(a, sep))
        if not s and not target:
            return 1.0
        if not s or not target:
            return 0.0
        return len(s & target) / len(s | target)
    return max(answers, key=lambda a: (score(a), -answers.index(a)))


def rule_modal_then_completest(answers, sep):
    """The modal answer, or the most complete reply that contains it."""
    modal = rule_current(answers, sep)
    m = set(comps(modal, sep))
    supersets = [a for a in answers if m <= set(comps(a, sep))]
    return max(supersets, key=len) if supersets else modal


def rule_union_modal(answers, sep):
    """The union of every reply that agrees with the modal answer on at least half its pieces."""
    modal = rule_current(answers, sep)
    m = set(comps(modal, sep))
    keep = [a for a in answers if len(set(comps(a, sep)) & m) >= max(1, len(m) / 2)]
    union = set()
    for a in keep:
        union |= set(comps(a, sep))
    for a in answers:
        if set(comps(a, sep)) == union:
            return a
    return modal


RULES = {
    'current': rule_current,
    'longest': rule_longest,
    'shortest': rule_shortest,
    'comp_maj': rule_component_majority,
    'modal_completest': rule_modal_then_completest,
    'union_modal': rule_union_modal,
}


