            out[name][task + '_n'] += 1
        out['recorded'][task] += correct(task, row['target'], row['prediction'])
        out['recorded'][task + '_n'] += 1
    names = ['recorded'] + list(RULES)
    for name in names:
        line = [f'{name:16s}']
        accs = []
        for task in TASKS:
            n = out[name][task + '_n']
            c = out[name][task]
            line.append(f'{task[:6]}={c:3d}/{n:3d}={c/n:.3f}' if n else f'{task[:6]}=n/a')
            if n:
                accs.append(c / n)
        line.append(f'mean={sum(accs)/len(accs):.4f}')
        print(' '.join(line))


