"""How the exact-answer panel vote scores as a function of panel size, on pooled raw replies.

Replies are pooled per example across the five recorded runs (every run re-asks the same
question from the same frozen memory and the same prompt), grounded with the shipped module,
and voted on with the shipped rule.  Random partitions of size k estimate what a panel of k
attempts would score.
"""
import json, random, sys, collections
sys.path.insert(0, '/tmp/analysis')
from extract import RUNS, TASKS, load
from rules import A, correct, TASKS

KS = [1, 2, 3, 5, 8, 12]
DRAWS = 200


def pool():
    runs = {k: load(k) for k in RUNS}
    pooled = collections.defaultdict(list)
    for run_key, rows in runs.items():
        for (task, ex, s), row in rows.items():
            if ex is None:
                continue
            for reply in row['replies']:
                pooled[(task, ex)].append(reply)
    targets = {}
    for run_key, rows in runs.items():
        for (task, ex, s), row in rows.items():
            if ex is not None and row['target']:
                targets[(task, ex)] = row['target']
    return pooled, targets


def main():
    pooled, targets = pool()
    spaces = {t: A.load_answer_space(f'{RUNS["panel"]}/{t}/memory.json') for t in TASKS}
    rng = random.Random(0)
    out = collections.defaultdict(lambda: collections.Counter())
    for (task, ex), replies in sorted(pooled.items()):
        target = targets.get((task, ex))
        if not target:
            continue
        grounded = [A.answer_text(A.ground_reply(r, spaces[task])) for r in replies]
        n = len(grounded)
        for k in KS:
            if k > n:
                continue
            for _ in range(DRAWS if k < n else 1):
                pick = rng.sample(grounded, k)
                ans = pick[A.panel_winner(pick)]
                out[k][task] += correct(task, target, ans)
                out[k][task + '_n'] += 1
        # first reply alone
        out[0][task] += correct(task, target, grounded[0])
        out[0][task + '_n'] += 1
        out['replies'][task] += n
        out['replies'][task + '_n'] += 1
    print('pool mean replies/sample:', {t: out['replies'][t] / out['replies'][t + '_n'] for t in TASKS})
    for k in [0] + KS:
        line = [f'k={k:2d}']
        accs = []
        for task in TASKS:
            n = out[k][task + '_n']
            if not n:
                continue
            a = out[k][task] / n
            line.append(f'{task[:6]}={a:.4f}')
            if k in KS:
                accs.append(a)
        if accs:
            line.append(f'mean={sum(accs)/len(accs):.4f}')
        print(' '.join(line))


if __name__ == '__main__':
    main()

