"""Selection rules that rank the panel's replies by how much the memory supports them."""
import collections, random, sys
sys.path.insert(0, '/tmp/analysis')
from poolcurve import pool
from rules import A, correct, TASKS

KS = [3, 5, 8]
DRAWS = 300


def pieces(answer, sep):
    text = (answer or '').strip()
    if sep and sep in text:
        return [p.strip() for p in text.split(sep) if p.strip()]
    return [text] if text else []


def mode(answers):
    counts = collections.OrderedDict()
    for a in answers:
        counts.setdefault(a, []).append(a)
    best = max(counts, key=lambda k: len(counts[k]))
    return best


def rule_mode(answers, items, sep):
    return mode(answers)


def rule_mem_exact(answers, items, sep):
    """Prefer the replies whose answer the memory demonstrates; the mode decides among them."""
    supported = [a for a in answers if a.strip() in items]
    return mode(supported) if supported else mode(answers)


def rule_mem_pieces(answers, items, sep):
    """Prefer the replies every piece of which the memory demonstrates."""
    supported = [a for a in answers if pieces(a, sep) and all(p in items for p in pieces(a, sep))]
    return mode(supported) if supported else mode(answers)


def rule_mem_frac(answers, items, sep):
    """Rank by how much of the answer the memory demonstrates, then by panel frequency."""
    counts = collections.Counter(answers)
    def key(a):
        ps = pieces(a, sep)
        frac = sum(1 for p in ps if p in items) / len(ps) if ps else 0.0
        return (frac, counts[a], -answers.index(a))
    return max(answers, key=key)


def rule_mem_frac_mode(answers, items, sep):
    """Mode first, and only answers the memory fully demonstrates can outrank the mode."""
    counts = collections.Counter(answers)
    full = [a for a in answers if pieces(a, sep) and all(p in items for p in pieces(a, sep))]
    if full:
        return mode(full)
    return mode(answers)


RULES = {
    'mode': rule_mode,
    'mem_exact': rule_mem_exact,
    'mem_pieces': rule_mem_pieces,
    'mem_frac': rule_mem_frac,
    'mem_frac_fallback': rule_mem_frac_mode,
}


def main():
    pooled, targets = pool()
    spaces = {t: A.load_answer_space(f'/workspace/runs/fb204702a72dc3e2168539118386bdb4a460371c/{t}/memory.json')
              for t in TASKS}
    items = {t: set(spaces[t]['items']) for t in TASKS}
    rng = random.Random(1)
    # fixed example subset: those with at least max(KS) replies
    keep = [key for key, replies in pooled.items()
            if len(replies) >= max(KS) and targets.get(key)]
    print('examples used:', len(keep))
    out = collections.defaultdict(lambda: collections.Counter())
    for key in keep:
        task, ex = key
        target = targets[key]
        grounded = [A.answer_text(A.ground_reply(r, spaces[task])) for r in pooled[key]]
        sep = spaces[task].get('separator')
        for k in KS:
            for _ in range(DRAWS):
                pick = rng.sample(grounded, k)
                for name, fn in RULES.items():
                    ans = fn(pick, items[task], sep)
                    out[(name, k)][task] += correct(task, target, ans)
                    out[(name, k)][task + '_n'] += 1
    for k in KS:
        for name in RULES:
            line = [f'k={k} {name:18s}']
            accs = []
            for task in TASKS:
                n = out[(name, k)][task + '_n']
                if not n:
                    continue
                a = out[(name, k)][task] / n
                line.append(f'{task[:6]}={a:.4f}')
                accs.append(a)
            line.append(f'mean={sum(accs)/len(accs):.4f}')
            print(' '.join(line))
        print()


if __name__ == '__main__':
    main()

